head.script:
// https://inswave01.atlassian.net/browse/WAEA-936



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellDataType]<br/>Body Cell 정보를 사용하여 특정 Body Cell 의 dataType 속성을 설정합니다.",
    "validation" : [
        "Column 의 inputType 이 'custom' 이고, Cell 의 inputType 속성값이 'text','textarea','secret' 인 경우에만 동작합니다.",
        "rowIndex(필수) 파라미터로 dataType 속성을 설정할 Body Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "columnInfo(필수) 파라미터로 dataType 속성을 설정할 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "dataType(필수) 파라미터로 'number' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'float' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'bigDecimal' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'text' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'date' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'time' 를 설정하여 Cell 의 dataType 속성을 변경할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

	$c.gcm.createLabel('label="[전제] custom text·secret Cell 을 더블클릭하면 편집 input 으로 진입해 값을 입력할 수 있습니다. (초기값 빈값)\n[절차] rowIndex / columnInfo / dataType 선택 후 setCellDataType 실행 -> 해당 Cell 을 더블클릭해 값 입력 후 포커스 아웃하면 리턴창에 표시값이 출력됩니다.\n[확인] dataType 별로 입력 문자가 제한되고(숫자형=숫자/부호/소수점, text/date/time=제한없음), dataType 에 맞는 표시 포맷이 함께 적용됩니다. (number 1234.5 -> 1,234.5 / date 20231225 -> 2023-12-25)"', '', 'label1');

    // dataList 생성 + 빈값 바인딩
    //  사용자가 직접 셀에 값을 입력하는 흐름이므로 초기값은 모두 빈 문자열로 둔다.
    let strNameSpace = $c.gcm.getNameSpace();
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "", "col2": "" },
        { "col1": "", "col2": "" },
        { "col1": "", "col2": "" },
        { "col1": "", "col2": "" }
    ]);

    // target 생성 (정상 편집 : 셀 더블클릭 -> 편집 input 오버레이. accessibility 미사용)
    //  편집 진입(더블클릭) 시 셀 td 의 자식이 아니라 별도 오버레이 input(id="G_{gridId}__{colId}", class="w2input w2input_focus") 이 생성됨
    //  실제 편집·setCellDataType 동작이 가능한 custom text·secret Cell 만 남김(축소 구성).
    //  col1 : inputType=custom + typeGetter(Cell inputType=text)     -> 편집 O / setCellDataType 동작 대상 (text)
    //  col2 : inputType=custom + typeGetter(Cell inputType=secret)   -> 편집 O / setCellDataType 동작 대상 (secret)
    // 이벤트 바인딩 (createEList 공통 함수) : onafteredit (셀 편집 후 포커스 아웃 시 표시값 출력)
    let eList = $c.gcm.createEList(["onafteredit"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:520px;height:200px;" ' + eList + '>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="200" inputType="text" id="hcol1" value="Cell text (custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="Cell secret (custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="200" inputType="custom" dataType="text" id="col1" dataList="col1" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" dataType="text" id="col2" dataList="col2" typeGetter="scwin.target1_secretTypeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// col1(custom) : 각 Cell 을 inputType=text 로 구성 -> setCellDataType 동작 가능 (허용 4종)
scwin.target1_textTypeGetter = function (info) {
    return {
        id: 'cell_text_' + info.rowIndex + '_' + info.colIndex,
        inputType: 'text',
        options: { textAlign: 'right' }
    };
};



// col2(custom) : 각 Cell 을 inputType=secret 로 구성 -> setCellDataType 동작 가능 (허용 4종)
scwin.target1_secretTypeGetter = function (info) {
    return {
        id: 'cell_secret_' + info.rowIndex + '_' + info.colIndex,
        inputType: 'secret',
        options: {}
    };
};





// ★ 셀 편집 후 포커스 아웃(편집모드 종료) 시 발생 -> 해당 Cell 의 표시값(포맷 적용된 화면값)을 리턴창에 출력
//  getCellDisplayData(rowIndex, columnInfo) : displayFormat 등이 적용된 화면 표시값을 반환
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    let dispVal = "";
    try {
        dispVal = scwin.target1.getCellDisplayData(rowIndex, columnIndex);
    } catch (e) {
        dispVal = "(표시값 조회오류)";
    }
    wf_body_bottom.getObj("scwin").setReturnValue(
        "onafteredit(row " + rowIndex + ", col " + columnIndex + ") 입력값 : " + value + " | 표시값 : " + dispVal);
};



// 해당 Cell 의 dataType 속성값을 조회 (custom 컬럼은 Cell 단위 cellManager.options.dataType, 그 외는 Column 단위)
//  setCellDataType 은 Cell 단위 dataType 을 변경하므로 Cell 단위 값으로 변경 전/후를 확인한다.
scwin.getCellDataType = function (rowIndex, columnInfo) {
    let api = scwin.target1;
    let colIndex = api.getColumnIndex(columnInfo);
    let cellInfo = api.getCellInfo(colIndex);
    if (cellInfo && cellInfo.options && cellInfo.options.inputType === "custom") {
        let realRow = api.dataList.getRealRowIndex(rowIndex);
        let cm = cellInfo.cellManagerHashByRowIndex ? cellInfo.cellManagerHashByRowIndex[realRow] : null;
        return cm && cm.options ? "(Cell) " + cm.options.dataType : "(Cell 미생성)";
    }
    return cellInfo && cellInfo.options ? "(Column) " + cellInfo.options.dataType : "(미확인)";
};



// setCellDataType 실행 : Cell 의 dataType 속성을 변경하고 변경 전/후 dataType 을 리턴창에 출력한다.
//  실측(정상 편집 더블클릭, 포트 65522, MCP):
//   - text(col0) / secret(col1)   : (Cell)text -> (Cell)number 로 dataType 변경됨 (동작). 더블클릭 편집 input 생성됨.
//  ※ dataType 의 실제 효과는 편집 input 에서의 "입력 문자 제한"으로 나타난다(MCP 실측):
//    number/float/bigDecimal 등 숫자형 = 숫자/부호/소수점만 입력(예 "a1b2.3+c-" -> "12.3+-"), text/date/time = 제한 없음.
//    dataType 변경 자체(Cell.options.dataType)도 정상 동작(text/secret 한정, textarea/input 은 엔진 결함).
// dataType 별 displayFormat 매핑 (MCP 실측으로 확정)
//  number → #,##0.##  (예 1234.5 → 1,234.5)
//  float  → #,##0.00## (예 1234.5 → 1,234.50)
//  bigDecimal → #,##0.00 (예 1234.5 → 1,234.50)
//  date   → yyyy-MM-dd (예 20231225 → 2023-12-25)
//  time   → HH:mm:ss   (예 123456 → 12:34:56)
//  text   → 포맷 없음(빈 문자열)
scwin.getDisplayFormatByType = function (dataType) {
    switch (dataType) {
        case "number":     return "#,##0.##";
        case "float":      return "#,##0.00##";
        case "bigDecimal": return "#,##0.00";
        case "date":       return "yyyy-MM-dd";
        case "time":       return "HH:mm:ss";
        case "text":       return "";
        default:           return "";
    }
};

scwin.btn_setCellDataType_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnInfo = Number(par_columnInfo.getValue());
    let dataType = par_dataType.getValue();

    // 변경 전 Cell dataType 속성값
    let beforeType = scwin.getCellDataType(rowIndex, columnInfo);

    // 메소드 반환값 (전제 미충족 시 false 반환)
    let ret = scwin.target1.setCellDataType(rowIndex, columnInfo, dataType);

    // ★ dataType 에 맞는 표시 포맷(displayFormat) 도 같은 Cell 에 함께 적용
    //  setCellDisplayFormat(rowIndex, columnInfo, displayFormat) : custom 셀 displayFormat 설정
    //  -> 셀 편집·커밋 후 표시값이 타입별로 포맷되어 보인다.
    let fmt = scwin.getDisplayFormatByType(dataType);
    try { scwin.target1.setCellDisplayFormat(rowIndex, columnInfo, fmt); } catch (e) {}

    // 화면 갱신 (셀 단위 재렌더)
    try { scwin.target1.refreshCell(rowIndex, columnInfo); } catch (e) {}

    // 변경 후 Cell dataType 속성값
    let afterType = scwin.getCellDataType(rowIndex, columnInfo);

    let changed = (beforeType !== afterType);
    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellDataType(" + rowIndex + ", " + columnInfo + ", '" + dataType + "')"
        + " + setCellDisplayFormat(" + rowIndex + ", " + columnInfo + ", '" + fmt + "')"
        + " | 변경 전 dataType : " + beforeType + " -> 변경 후 dataType : " + afterType
        + " | 변경됨 : " + changed
        + " | (해당 Cell 에 값을 입력하고 포커스 아웃하면 dataType 별 포맷이 적용된 표시값이 출력됩니다.)"
        + (ret === false ? " (전제 미충족 -> 미동작)" : ""));
}
